INSERT INTO "public"."dev_lessons" ("id", "theme_id", "theme_name", "development_mode", "age_group", "lesson_number", "title", "biblical_reference", "biblical_story", "reflection", "challenge", "final_message", "share_summary", "created_at") VALUES
('a1a87603-fb01-4373-b3af-4aa71ca1db45', 'honestidade', 'Honestidade', 'personal', 'adulto', 7, 'A Coragem de Reparar os Erros', 'Lucas 19:1-9', 'Jesus entrou em Jericó e atravessava a cidade. Havia ali um homem rico chamado Zaqueu, chefe dos cobradores de impostos. Sendo de baixa estatura, ele correu adiante e subiu em uma figueira brava para ver Jesus passar. Ao chegar àquele lugar, Jesus olhou para cima e lhe disse: "Zaqueu, desça depressa, pois hoje preciso ficar em sua casa". Zaqueu desceu depressa e o recebeu com grande alegria. A multidão, ao ver isso, murmurava dizendo que Jesus havia entrado para ser hóspede de um pecador. Então Zaqueu levantou-se e disse ao Senhor: "Eis que dou a metade dos meus bens aos pobres; e, se extorqui algo de alguém, restituo quatro vezes mais". Jesus lhe declarou: "Hoje houve salvação nesta casa, pois este homem também é filho de Abraão".', 'O verdadeiro alinhamento moral com Deus exige mais do que pesar de consciência; requer ação concreta. Zaqueu não ofereceu justificativas ou promessas vagas, mas assumiu a responsabilidade pelos danos causados, abrindo mão do ganho desonesto. Integridade genuína envolve a coragem de examinar o passado, reparar prejuízos financeiros ou morais causados a outros e adotar transparência absoluta no trato com os bens. Quando a honestidade guia nossas decisões, o arrependimento deixa de ser mero discurso e se torna retidão prática na administração da vida e dos relacionamentos.', 'Identifique uma pendência do passado e inicie hoje a reparação devida com retidão.', 'A integridade autêntica conserta o passado para edificar um futuro reto.', 'A verdadeira honestidade vai além do arrependimento: ela exige reparação e atitudes práticas. Assim como Zaqueu restituiu o que obteve injustamente, somos chamados a consertar pendências e viver com retidão. Quando corrigimos nossos erros, a integridade se estabelece em nossa história.', NOW()),
('3e827ef6-0d0e-4202-a727-bc761fc1e368', 'honestidade', 'Honestidade', 'kids', 'kids', 7, 'Zaqueu e a Coragem de Consertar', 'Lucas 19:1-9', 'Jesus entrou na movimentada cidade de Jericó. Naquele lugar vivia um homem chamado Zaqueu, chefe dos cobradores de impostos e muito rico. Ele queria muito ver Jesus, mas não conseguia porque era muito baixinho e a multidão cobria sua visão. Então, Zaqueu correu na frente de todos e subiu nos galhos de uma grande figueira para poder enxergá-lo. Quando Jesus passou por ali, olhou para cima e chamou: "Zaqueu, desça depressa, pois hoje devo ficar em sua casa". Ele desceu feliz e acolheu o Mestre com festa. Diante do amor de Jesus, Zaqueu decidiu mudar suas atitudes e disse: "Senhor, darei metade dos meus bens aos pobres e, se tirei algo de alguém injustamente, pagarei quatro vezes mais". Jesus declarou alegremente que a salvação havia entrado naquela casa.', 'Assim como um jardineiro cuida de um galho quebrado para a planta voltar a florir, a honestidade conserta o que estragamos. Zaqueu percebeu que não bastava apenas pedir desculpas; ele quis devolver o que tirou e curar a tristeza que causou. Quando pegamos um brinquedo sem pedir ou dizemos algo que machuca, o coração fica pesado. Mas, quando confessamos e consertamos o erro com carinho e verdade, nosso lar se enche de paz e a alegria verdadeira brota outra vez.', 'Devolva um objeto emprestado ou peça desculpas sinceras a quem você magoou hoje.', 'A honestidade verdadeira sempre repara os erros com amor e atitudes.', 'Aprendemos hoje com Zaqueu que a honestidade de verdade não fica só nas palavras, mas conserta os erros do passado.
