INSERT INTO "public"."dev_prayers" ("id", "lesson_id", "role", "text_content", "display_order") VALUES
('87346d77-3fa0-44bd-b0a0-9813843b7600', 'a1a87603-fb01-4373-b3af-4aa71ca1db45', 'Individual', 'Senhor, sonda o meu coração e revela onde falhei com a justiça e a honestidade. Dá-me coragem e prontidão para reparar danos, pagar o que devo e agir com total retidão diante de Ti e das pessoas. Que a Tua verdade governe as minhas escolhas materiais e morais. Amém.', 1),
('72b96845-00f4-424b-9885-6309495d6fc7', '3e827ef6-0d0e-4202-a727-bc761fc1e368', 'Pai', 'Senhor, ensina-me a ser exemplo de retidão e a ter coragem para consertar meus erros diante da minha família.', 1),
('82bb1362-163e-4b45-8b4f-8fa2306974b0', '3e827ef6-0d0e-4202-a727-bc761fc1e368', 'Filho', 'Papai do Céu, me ajuda a sempre devolver o que não é meu e a dizer a verdade sem medo.', 2),
('e9dbbb68-e696-4f89-b635-f68803e738b1', '3e827ef6-0d0e-4202-a727-bc761fc1e368', 'Juntos', 'Amado Jesus, transforma o nosso lar em um lugar de justiça, perdão e honestidade todos os dias. Amém.', 3),
('644f307d-2f50-46cf-9a1b-ff80aea9e3f5', '8b983b9d-9d83-4e15-85c0-8742f695f759', 'Pai', 'Senhor, dá-me humildade para reconhecer minhas falhas e coragem para ensinar meus filhos a reparar erros com retidão.', 1),
('48976ce6-acba-4065-a2f3-30a9a50a584d', '8b983b9d-9d83-4e15-85c0-8742f695f759', 'Filho', 'Jesus, ajuda-me a não fugir das consequências dos meus atos e a consertar o que fiz de errado com meus amigos e familiares.', 2),
('c0f186af-6255-47f7-aaf1-356069258778', '8b983b9d-9d83-4e15-85c0-8742f695f759', 'Juntos', 'Pai Celestial, que a nossa casa viva a alegria da honestidade que restaura a paz e honra o Teu santo nome. Amém.', 3),
('e3717860-af2c-4c75-8146-4f5d0a9c3880', 'c34441fb-8e9e-4433-8ece-4dfa022ba911', 'Pai', 'Senhor, dá-me sabedoria para ensinar meus filhos pelo exemplo de retidão e restituição.', 1),
('695469d9-b3be-4e62-9a0e-da77d30c8873', 'c34441fb-8e9e-4433-8ece-4dfa022ba911', 'Filho', 'Pai celeste, conceda-me coragem para admitir minhas falhas e consertar os danos que causei.', 2),
('4888d27e-db4f-45d1-bab0-2337d1a67de4', 'c34441fb-8e9e-4433-8ece-4dfa022ba911', 'Juntos', 'Deus eterno, que a nossa casa seja marcada pela transparência, justiça e honestidade sincera. Amém.', 3),
('24997a55-35c6-47ff-92df-0fe3a5057008', '3759048f-684b-4335-8159-138ec6096faa', 'Individual', 'Senhor Deus, purifica os meus lábios e o meu coração de toda falsidade. Dá-me coragem para falar a verdade com amor, mantendo a firmeza e a retidão em minhas relações diárias. Que a integridade guie cada palavra minha. Amém.', 1),
('9f37a0af-8b6d-4097-a24d-e242c1868445', 'cb38f116-e08e-4b83-bbda-a1ffd6fad9b8', 'Pai', 'Senhor, ajuda-me a ser um exemplo de sinceridade e a guiar nossa casa na Tua luz.', 1),
('fbe77f8b-8a24-42fc-809b-5c4c1e3a8621', 'cb38f116-e08e-4b83-bbda-a1ffd6fad9b8', 'Filho', 'Jesus, me dê coragem para falar sempre a verdade e cuidar da minha família.', 2),
('76f1e525-2578-454b-8df6-800ac023119d', 'cb38f116-e08e-4b83-bbda-a1ffd6fad9b8', 'Juntos', 'Pai do Céu, que a verdade e o amor estejam sempre presentes em nosso lar. Amém.', 3),
('b2186ce6-ef08-481a-8c30-5bc042a889e0', '6f9aa6d6-c075-4cce-9baf-ba117f471819', 'Pai', 'Senhor, ajuda-me a liderar meu lar com transparência e paciência para acolher a verdade sempre.', 1),
('dfd23c81-dd1c-4c08-9c15-2de3e9885a0e', '6f9aa6d6-c075-4cce-9baf-ba117f471819', 'Filho', 'Deus, dá-me coragem para falar a verdade e rejeitar a mentira diante dos meus amigos e da família.', 2),
('c3e69d44-2831-42ee-9020-2135c6dda7f7', '6f9aa6d6-c075-4cce-9baf-ba117f471819', 'Juntos', 'Pai celestial, fortalece nossa união através da verdade e faz da nossa casa um lugar de confiança mútua. Amém.', 3),
('3410220b-e431-4310-91cb-e928ba991bb3', '48581961-6d07-4dea-9673-48afa100e326', 'Pai', 'Senhor, ensina-me a ser um exemplo irrepreensível de verdade para guiar minha família no caminho da retidão.', 1),
('cb127b6d-965f-4cad-82b2-91c5b2e93e2e', '48581961-6d07-4dea-9673-48afa100e326', 'Filho', 'Deus, dá-me coragem para sempre falar a verdade aos meus pais, mesmo quando errar ou sentir medo.', 2),
('42f4dc26-45c4-45e6-8ad2-2e1cd5ae887c', '48581961-6d07-4dea-9673-48afa100e326', 'Juntos', 'Pai Celestial, ajuda nossa casa a rejeitar todo engano e a viver unida pela sinceridade e integridade. Amém.', 3),
('8016124c-c8d2-4e04-820e-aa26188e43f2', 'd24e5646-6b35-469c-a202-17b50b04b636', 'Individual', 'Senhor Deus, concede-me sabedoria e retidão para agir com total transparência em todas as minhas responsabilidades. Que a minha conduta seja irrepreensível tanto aos Teus olhos quanto diante das pessoas ao meu redor. Livra-me do orgulho de agir isoladamente e ensina-me a valorizar a prestação de contas, preservando a honra do Teu nome em cada detalhe do meu trabalho e da minha vida. Amém.', 1),
('cdae47da-e069-4dda-a9c6-78833a57a325', 'edf8c82f-3bf9-4ee3-a0eb-7f69bfc13e44', 'Pai', 'Senhor, ajuda-nos a liderar nosso lar com integridade visível e honrar Teu nome perante todos.', 1),
('6f53c312-e8d8-461b-adc9-2fcedda7607f', 'edf8c82f-3bf9-4ee3-a0eb-7f69bfc13e44', 'Filho', 'Papai do Céu, quero ser sincero e fazer as coisas certas para todos verem Tua luz.', 2),
('e024d209-5d3d-45a2-bc9c-7c0f70b0b6fc', 'edf8c82f-3bf9-4ee3-a0eb-7f69bfc13e44', 'Juntos', 'Que nossa família seja transparente e alegre como água limpa que reflete Teu amor. Amém.', 3),
('15416f83-ca09-4bb1-8928-59e9df5fcd24', 'fe5c5041-dce1-42b8-a877-8296ba8c721c', 'Pai', 'Senhor, ajuda-me a liderar meu lar com transparência e a ser um exemplo visível de retidão no trabalho e na família.', 1),
('8858a44a-3bb3-43cd-912a-ac2661db0cfa', 'fe5c5041-dce1-42b8-a877-8296ba8c721c', 'Filho', 'Pai do Céu, livra-me do engano e da pressão dos colegas, para que minhas ações na escola tragam honra ao Teu nome.', 2),
('074da1f0-fb2a-4e4e-add2-27fe62a0d683', 'fe5c5041-dce1-42b8-a877-8296ba8c721c', 'Juntos', 'Deus eterno, firma nossa família na honestidade absoluta, diante dos Teus olhos e de todas as pessoas. Amém.', 3),
('d931fc6a-e43c-4d03-99ad-d46666cd4f3d', '8ff26d87-6ccc-47da-b1e8-3ee4917eeef9', 'Pai', 'Senhor, ajuda-me a liderar com exemplo límpido, ensinando transparência em cada decisão da nossa casa.', 1),
('89c93905-b41c-46d7-bd22-5b94f1f86bff', '8ff26d87-6ccc-47da-b1e8-3ee4917eeef9', 'Filho', 'Deus, dá-me coragem para agir às claras, prestando contas com sinceridade e honrando a Tua palavra.', 2),
('1588ad78-7cb9-401a-b839-6c241f7052cf', '8ff26d87-6ccc-47da-b1e8-3ee4917eeef9', 'Juntos', 'Pai celestial, firma nossa família na retidão, para que nosso testemunho seja irrepreensível diante de todos. Amém.', 3),
('f5282ca3-2b40-4057-a5e5-275029dc1ff5', '7ff05bfa-6188-49f5-b69d-d19e44445c15', 'Individual', 'Senhor Deus, concede-me a firmeza necessária para manter minha consciência limpa em todas as situações. Ensina-me a não ceder ao medo ou à conveniência quando os princípios da verdade forem provados. Que o meu testemunho seja coerente, sincero e fiel diante de Ti e dos homens, hoje e sempre. Amém.', 1),
('efcb6bf7-efb8-4679-b820-e89279cc0e69', '2cd31867-0cf5-421e-a9e6-6b95f2e2d33b', 'Pai', 'Senhor, ajuda-nos a ensinar e viver a verdade com amor e coragem todos os dias.', 1),
('85486fa9-62c4-4e9d-a239-8f5371cffa43', '2cd31867-0cf5-421e-a9e6-6b95f2e2d33b', 'Filho', 'Papai do Céu, me ajude a ser corajoso e falar sempre a verdade sem medo.', 2),
('5ca2c283-0cb6-42dd-8d09-dcd5266055ec', '2cd31867-0cf5-421e-a9e6-6b95f2e2d33b', 'Juntos', 'Senhor, guarde nossa família para termos sempre um coração limpo e sincero. Amém.', 3),
('74f11622-34ef-4c11-bd47-e5ae0fd884b8', '60b5a1b2-649a-4ceb-8d35-097638898055', 'Pai', 'Senhor, dá-nos coragem para viver com retidão e ensinar a verdade sem temer pressões externas.', 1),
('eac6be81-9848-4e31-8a79-f2aa7339ee37', '60b5a1b2-649a-4ceb-8d35-097638898055', 'Filho', 'Pai celestial, ajuda-me a manter minha consciência limpa e a nunca mentir para agradar outras pessoas.', 2),
('861432d3-bddf-466e-a2dc-10129bd5bdbc', '60b5a1b2-649a-4ceb-8d35-097638898055', 'Juntos', 'Que a verdade de Cristo guie nossas palavras e atitudes em qualquer lugar onde estivermos. Amém.', 3),
('439ce0d3-f11b-43ef-8ef2-cb54a594d008', 'f882ac49-823c-411f-980e-da5142940e77', 'Pai', 'Senhor, capacita-me a liderar meu lar com retidão e a incentivar meu filho a amar a verdade.', 1),
('1dff561c-90f3-48c3-8a81-0456b57ee067', 'f882ac49-823c-411f-980e-da5142940e77', 'Filho', 'Pai celeste, dá-me firmeza para nunca negociar meus valores, mantendo minha consciência limpa em secreto.', 2),
('f3ba5d1b-2f88-4d53-8261-4280f001c7b3', 'f882ac49-823c-411f-980e-da5142940e77', 'Juntos', 'Deus eterno, guarda a nossa família em Tua santidade para que vivamos com integridade até o fim. Amém.', 3);
